#include <numeric>

using namespace std;

class Solution {
public:
    double average(vector<int>& salary) {
        // Find min and max elements
        int min_val = *min_element(salary.begin(), salary.end());
        int max_val = *max_element(salary.begin(), salary.end());

        // Calculate sum excluding min and max
        double sum = 0;
        for (int s : salary) {
            if (s != min_val && s != max_val) {
                sum += s;
            }
        }

        // Count elements excluding min and max
        int count = 0;
        for (int s : salary) {
            if (s != min_val && s != max_val) {
                count++;
            }
        }

        return sum / count;
    }
};
